package com.zoro.zoromart.service;
import com.google.gson.*;import java.net.URI;import java.net.http.*;import java.time.Duration;
/** Optional Gemini provider. The API key is read only from the server environment. */
public class GeminiChatProvider implements ChatProvider {private final String key;public GeminiChatProvider(){key=System.getenv("GEMINI_API_KEY");}public String getReply(String userMessage,String context)throws Exception{if(key==null||key.isBlank())throw new IllegalStateException("GEMINI_API_KEY is not configured");JsonObject part=new JsonObject();part.addProperty("text","You are ZoroMart's product FAQ assistant. Answer only questions about products, listings, cart, checkout, orders, sellers and reviews. If unrelated, politely redirect to those topics. Context: "+context+"\nUser: "+userMessage);JsonObject content=new JsonObject();JsonArray parts=new JsonArray();parts.add(part);content.add("parts",parts);JsonArray contents=new JsonArray();contents.add(content);JsonObject payload=new JsonObject();payload.add("contents",contents);HttpRequest request=HttpRequest.newBuilder(URI.create("https://generativelanguage.googleapis.com/v1beta/models/gemini-1.5-flash:generateContent?key="+key)).timeout(Duration.ofSeconds(8)).header("Content-Type","application/json").POST(HttpRequest.BodyPublishers.ofString(payload.toString())).build();HttpResponse<String> response=HttpClient.newHttpClient().send(request,HttpResponse.BodyHandlers.ofString());if(response.statusCode()<200||response.statusCode()>=300)throw new IllegalStateException("AI provider returned status "+response.statusCode());JsonObject root=JsonParser.parseString(response.body()).getAsJsonObject();return root.getAsJsonArray("candidates").get(0).getAsJsonObject().getAsJsonObject("content").getAsJsonArray("parts").get(0).getAsJsonObject().get("text").getAsString();}}
